declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
if(empty($_SESSION['admin_id'])){ts_json_fail('REQ-102',401);}
if($_SERVER['REQUEST_METHOD']!=='POST'){ts_json_fail('REQ-101',405);}
$raw=(string)file_get_contents('php://input');$data=json_decode($raw,true);$endpoint=trim((string)($data['endpoint']??''));
